    # build a {value: count} dict
    pass

exercises.solution:
def frequency(xs):
    counts = {}
    for x in xs:
        counts[x] = counts.get(x, 0) + 1
    return counts

exercises.starter:
def group_by_parity(xs):
    # sort each number into the 'even' or 'odd' bucket
    pass

exercises.solution:
def group_by_parity(xs):
    groups = {'even': [], 'odd': []}
    for x in xs:
        if x % 2 == 0:
            groups['even'].append(x)
        else:
            groups['odd'].append(x)
    return groups

exercises.starter:
def tally_chars(s):
    # count each character into a {char: count} dict
    pass

exercises.solution:
def tally_chars(s):
    counts = {}
    for ch in s:
        counts[ch] = counts.get(ch, 0) + 1
    return counts

exercises.starter:
def group_by_first_letter(words):
    # group words into buckets by their first letter
    pass

exercises.solution:
def group_by_first_letter(words):
    groups = {}
    for word in words:
        groups.setdefault(word[0], []).append(word)
    return groups

exercises.starter:
def group_by_length(words):
    # group words into buckets by their length
    pass

exercises.solution:
def group_by_length(words):
    groups = {}
    for word in words:
        groups.setdefault(len(word), []).append(word)
    return groups
